namespace DevRecall.Infrastructure.Development;

public sealed partial class DogfoodDataSeeder
{
    private sealed record Concept(int Group, string Title, string Prompt, string Answer, string Pitfall);
    private static readonly string[] Groups = ["C# fundamentals", "Dependency injection", "Async and reliability", "EF Core and persistence", "HTTP API design", "Architecture", "Security", "Data structures"];

    private static readonly Concept[] Concepts =
    [
        new(0, "Value and reference semantics", "How do value and reference types differ when passed to a method?", "By default both are passed by value. A value-type value is copied; for a reference type the reference is copied, so both references can point at the same object. Reassigning the local reference does not replace the caller's variable.", "Do not confuse passing a reference by value with using ref."),
        new(0, "Equality and hash codes", "Why must equal objects return the same hash code?", "Hash-based collections use the hash to locate a bucket before comparing equality. Equal objects with different hashes can become unreachable as expected keys. Unequal objects may legitimately share a hash.", "Avoid mutating fields used in equality while an object is a dictionary key."),
        new(0, "Deferred LINQ execution", "What does deferred execution mean for a LINQ query?", "The query describes work that runs when enumerated. Enumerating twice can repeat work and can see different source data. Materialize deliberately when a stable reusable result is needed.", "ToList is not a substitute for filtering a database query before materialization."),
        new(0, "Disposal and ownership", "Who should dispose an IDisposable dependency?", "The component that owns the resource lifetime should dispose it. A using scope disposes resources it creates. Dependencies supplied by a container are normally disposed by the container or its scope.", "Do not dispose a shared injected dependency after each method call."),
        new(1, "Constructor injection", "Why is constructor injection useful for required dependencies?", "It makes required collaborators explicit and allows an object to be created in a valid state. Implementations can be supplied at the composition boundary and substituted in focused tests.", "A long constructor can reveal that a class has too many responsibilities."),
        new(1, "Service lifetimes", "How do Transient, Scoped and Singleton services differ?", "Transient creates an instance for each resolution. Scoped reuses an instance within a scope, commonly one HTTP request. Singleton reuses one instance for the container lifetime and must handle shared access safely.", "Singleton does not automatically make an object thread-safe."),
        new(1, "Captive dependencies", "Why is a Scoped dependency inside a Singleton dangerous?", "The Singleton can retain the shorter-lived dependency beyond its intended scope. Request state can be reused incorrectly and disposable resources may live too long. Resolve scoped work inside an explicit scope when appropriate.", "Changing everything to Singleton hides the lifetime problem rather than solving it."),
        new(1, "Composition root", "What belongs in an application's composition root?", "The composition root wires concrete implementations and lifetimes at the application boundary. Business code depends on its collaborators without knowing how the container constructs them.", "Avoid resolving arbitrary services inside business methods through a service locator."),
        new(2, "Task and await", "Does async/await automatically move work to another thread?", "No. A Task represents completion and await composes asynchronous work. Asynchronous I/O can release the waiting thread; CPU work still needs a deliberate execution strategy.", "Task.Run around database I/O does not make it more asynchronous."),
        new(2, "Cancellation propagation", "What should a method do with its caller's CancellationToken?", "Pass it to downstream operations that support cancellation and observe it at safe points during lengthy work. Cancellation is cooperative; it signals a request to stop rather than forcibly killing a thread.", "Do not replace the caller's token with CancellationToken.None without a specific reason."),
        new(2, "Blocking async code", "Why can Result or Wait be harmful around asynchronous work?", "Blocking occupies a thread while the operation waits, reducing scalability. In environments with a synchronization context it can also contribute to deadlocks. Prefer awaiting the operation through the call chain.", "Do not assume that wrapping a blocking call in an async method removes the blocking."),
        new(2, "Retry boundaries", "When is retrying a failed operation safe?", "Retry when the failure is transient and the operation is idempotent or protected against duplicate effects. Bound attempts and time, honor cancellation, and avoid repeating irreversible side effects blindly.", "A timeout can mean the server committed but the response was lost."),
        new(3, "Tracking queries", "When should an EF Core query usually use AsNoTracking?", "Use it for read-only results that will not be updated through that DbContext. Tracking provides change detection and identity management for updates; skipping it can avoid unnecessary overhead.", "Do not assume a detached entity will be saved without attaching or updating it deliberately."),
        new(3, "Transaction boundaries", "When is an explicit database transaction justified?", "A normal SaveChanges call is transactional with providers that support transactions. Use an explicit transaction when multiple operations must succeed or fail as one consistency boundary.", "Do not hold database transactions open while waiting on slow external HTTP calls."),
        new(3, "Optimistic concurrency", "How does an expected version detect a lost update?", "The update matches both the row ID and the previously read version. If another writer has changed the version, the update affects no matching row and the application surfaces or deliberately resolves the conflict.", "Do not automatically overwrite the newer row when catching a concurrency exception."),
        new(3, "Projection and pagination", "Why should filtering and pagination happen before materialization?", "The database can select only the requested rows and columns. Loading a whole table before filtering wastes memory, network transfer and query time, and becomes slower as the dataset grows.", "Pagination needs a stable ordering, including a tie-breaker."),
        new(4, "HTTP method semantics", "What is the practical difference between safe and idempotent HTTP operations?", "Safe operations are intended to read without changing application state. Idempotent operations have the same intended effect when repeated. An idempotent delete can still return a different status after the first request.", "Do not treat all POST requests as automatically safe to retry."),
        new(4, "Problem Details", "Why use a consistent machine-readable API error contract?", "Clients can distinguish validation, unavailable resources and conflicts using stable fields and codes. Human-readable explanations can change without breaking client logic. Unexpected implementation details stay on the server.", "Never expose database exceptions, stack traces or secrets in API responses."),
        new(4, "Validation boundaries", "How should request validation and domain invariants work together?", "Request validation rejects malformed or unsupported input near the boundary. Domain invariants protect valid state transitions regardless of the caller. Both are needed because the domain may be used outside HTTP.", "Frontend validation alone cannot protect stored data."),
        new(4, "Offset pagination", "What are the trade-offs of offset pagination?", "It is simple for ordinary management screens and supports page numbers. Deep offsets can become expensive and concurrent changes can shift rows between pages; stable ordering reduces ambiguity.", "Avoid materializing all rows merely to calculate or display a page."),
        new(5, "Dependency direction", "What does the dependency rule protect in Clean Architecture?", "Business policy can remain independent of delivery and persistence details. Outer layers implement inner abstractions, so changes in HTTP or storage need not reshape domain behavior.", "An interface alone does not make a dependency useful; give it a concrete boundary."),
        new(5, "Aggregate invariants", "Why expose business methods instead of public setters on an aggregate?", "Business methods describe allowed transitions and enforce invariants together. Public setters allow callers to construct combinations of state that a valid use case would never produce.", "Avoid an aggregate that loads every object in the system to enforce a small invariant."),
        new(5, "Read models", "Why can reporting queries use projections instead of loading aggregates?", "Reporting answers read-only questions and often benefits from SQL aggregation and compact DTOs. Aggregate behavior is valuable for transitions; it need not be invoked to count or summarize existing facts.", "A report should not create evidence or modify the resources it measures."),
        new(5, "Transactional orchestration", "Where should a multi-step use case coordinate persistence?", "The application use case coordinates domain operations within the required transaction boundary. Each aggregate still enforces its own rules, while infrastructure supplies transaction and persistence mechanisms.", "Avoid hidden fire-and-forget work after returning a successful HTTP response."),
        new(6, "Authentication and authorization", "Why can an authenticated user still be forbidden from reading a resource?", "Authentication establishes identity. Authorization evaluates whether that identity may perform the action on that resource, including ownership or policy requirements.", "Checking that a cookie exists is not an ownership check."),
        new(6, "Owner-scoped queries", "How do owner-scoped lookups protect private resources?", "Filter by the authenticated user as well as the requested ID. A resource owned by someone else should be treated according to the same unavailable-resource policy, without revealing private details.", "Never trust a userId supplied in the request body to establish the caller's identity."),
        new(6, "Cookie CSRF protection", "Why do cookie-authenticated mutations need CSRF protection?", "Browsers can send authentication cookies automatically. A server-issued token tied to the session helps distinguish the application's intended mutation requests from cross-site submissions.", "HttpOnly prevents JavaScript cookie access; it does not by itself prevent CSRF."),
        new(6, "Sensitive logging", "What should be excluded from application logs?", "Passwords, tokens, connection strings and private user content should not be logged. Use structured operation identifiers and correlation IDs to investigate failures without exposing those values.", "Request-body logging can leak secrets even when individual handlers do not log them."),
        new(7, "Hash lookup", "Why is a hash table useful for complement-search problems?", "It stores previously seen values for expected constant-time lookup. For Two Sum, look up target minus the current value before inserting the current index, preventing reuse of the same element.", "Check duplicates and remember that worst-case hashing behavior differs from average behavior."),
        new(7, "Stack invariants", "Why does a stack help validate nested parentheses?", "The most recently opened bracket must close first. Push opening types and compare each closing bracket against the top; a valid input finishes with an empty stack.", "Check an empty stack before popping and reject mismatched bracket types."),
        new(7, "Breadth-first search", "Why does BFS find shortest paths in an unweighted graph?", "The queue explores vertices in increasing edge-distance layers. Marking vertices when enqueued prevents duplicate work and the first discovery establishes a shortest edge-count distance.", "This guarantee does not extend directly to arbitrary weighted edges."),
        new(7, "Dynamic programming state", "What makes a useful dynamic programming state definition?", "A state captures enough information to describe a subproblem and derive it from smaller states. Define the transition, base cases and evaluation order before optimizing space.", "Do not cache by an incomplete state key or confuse greedy choices with a proven recurrence.")
    ];

    private sealed record Problem(string Title, string Pattern, string Prompt, string Approach, string Time, string Space);
    private static readonly Problem[] Problems =
    [
        new("Two Sum", "Hash map", "Return two distinct indices whose values sum to a target. Exactly one solution exists. Example: [2,7,11,15], target 9 → [0,1].", "Track previously seen values and look for target - value before inserting the current index.", "O(n)", "O(n)"),
        new("Valid Parentheses", "Stack", "Determine whether (), [] and {} are balanced and properly nested. Example: ([{}]) is valid; ([)] is not.", "Push opening brackets and require each closing bracket to match the latest opening bracket.", "O(n)", "O(n)"),
        new("Merge Intervals", "Sorting", "Merge overlapping closed intervals. Example: [[1,3],[2,6],[8,10]] → [[1,6],[8,10]].", "Sort by start and extend the last merged interval when the next start is within its end.", "O(n log n)", "O(n)"),
        new("Binary Search", "Binary search", "Find a target in a sorted unique integer array, or return -1. Example: [1,3,5,7], target 5 → 2.", "Maintain an inclusive search range and discard the half that cannot contain the target.", "O(log n)", "O(1)"),
        new("Longest Unique Substring", "Sliding window", "Find the longest substring without repeated characters. Example: abcabcbb → 3.", "Move the left boundary beyond a repeated character's previous position while tracking the best window.", "O(n)", "O(k)"),
        new("Maximum Subarray", "Dynamic programming", "Return the largest sum of a nonempty contiguous subarray. Example: [-2,1,-3,4,-1,2,1,-5,4] → 6.", "Track the best sum ending here: either start at the current value or extend the previous subarray.", "O(n)", "O(1)"),
        new("Number of Islands", "Graph traversal", "Count four-directionally connected groups of land in a grid of 0 and 1. Diagonal touching does not connect islands.", "For each unvisited land cell, traverse its component and increment the island count once.", "O(rows × columns)", "O(rows × columns)"),
        new("Binary Tree Level Order", "Breadth-first search", "Return tree values grouped by depth from root to leaves. An empty tree returns an empty list.", "Use a queue and process the queue length captured at the start of each level.", "O(n)", "O(n)"),
        new("Reverse Linked List", "Linked list", "Reverse a singly linked list and return the new head. Example: 1→2→3 becomes 3→2→1.", "Store the next pointer before redirecting the current node to the previous node.", "O(n)", "O(1)"),
        new("Linked List Cycle", "Two pointers", "Determine whether following next pointers in a linked list enters a cycle without changing the list.", "Advance slow by one and fast by two; a meeting implies a cycle, reaching null implies none.", "O(n)", "O(1)"),
        new("Product Except Self", "Prefix sums", "Return the product of every other element for each position without division. Example: [1,2,3,4] → [24,12,8,6].", "Store prefix products in the output and multiply by a rolling suffix product on a reverse pass.", "O(n)", "O(1) auxiliary"),
        new("Top K Frequent Elements", "Heap", "Return the k most frequent integers; assume k is between 1 and the number of unique values.", "Count frequencies then maintain a min-heap of at most k candidates.", "O(n + u log k)", "O(u + k)"),
        new("Course Schedule", "Topological sort", "Given prerequisite edges between courses, determine whether every course can be completed.", "Repeatedly remove vertices with zero indegree; processing all vertices means there is no directed cycle.", "O(V + E)", "O(V + E)"),
        new("Coin Change", "Dynamic programming", "Find the minimum number of positive-denomination coins for a target amount with unlimited supply; return -1 if impossible.", "For each amount, minimize one plus the best reachable amount after taking a coin; initialize zero to zero.", "O(amount × coins)", "O(amount)"),
        new("Climbing Stairs", "Dynamic programming", "Count ways to climb n steps taking one or two steps each time. Example: n=3 → 3.", "Ways for n equals ways for n-1 plus ways for n-2; keep only the previous two states.", "O(n)", "O(1)"),
        new("Validate Binary Search Tree", "Tree traversal", "Check whether every node satisfies strict BST ordering, including constraints inherited from ancestors.", "Carry lower and upper bounds down the tree rather than comparing only immediate children.", "O(n)", "O(h)"),
        new("Minimum Window Substring", "Sliding window", "Find the shortest substring containing all target characters with their multiplicities; return empty if absent.", "Expand until all required counts are met, then shrink while preserving validity.", "O(n + m)", "O(k)"),
        new("Search Rotated Sorted Array", "Binary search", "Find a target in a rotated sorted array of distinct values. Example: [4,5,6,7,0,1,2], target 0 → 4.", "Identify the sorted half each iteration and test whether the target lies in that half.", "O(log n)", "O(1)"),
        new("LRU Cache", "Hash map and linked list", "Design Get and Put with average constant-time cost and evict the least recently used key at capacity.", "Combine a dictionary of nodes with a doubly linked recency list; move accessed nodes to the front.", "O(1) average per operation", "O(capacity)"),
        new("Daily Temperatures", "Monotonic stack", "For each daily temperature, return how many days until a warmer temperature; use zero when none exists.", "Keep unresolved indices in a decreasing-temperature stack and resolve them when a warmer day arrives.", "O(n)", "O(n)")
    ];
